package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.role.SheetRole;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The periods on a sheet: named, each running from a day to a day, none overlapping another. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final Dues dues;
    private final RoleService roles;
    private final History history;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetService sheets, ClaimRepository claims,
            PersonRepository people, Dues dues, RoleService roles, History history, Audit audit) {
        this.history = history;
        this.periods = periods;
        this.sheets = sheets;
        this.claims = claims;
        this.people = people;
        this.dues = dues;
        this.roles = roles;
        this.audit = audit;
    }

    /** The periods on the sheet, earliest first. */
    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    /** Add a period, capping each person's open or pending claims in it when a cap is given (null:
     *  none); refused when its to-date is before its from-date, its cap is below 1, its name is in use
     *  on the sheet, or it shares a day with another period. */
    @Transactional
    public synchronized Period add(String sheetId, String user, String name, LocalDate from, LocalDate to,
            Integer cap) {
        sheets.load(sheetId, user);
        if (cap != null && cap < 1) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's claim cap must be at least 1");
        }
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts");
        }
        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
            throw nameInUse();
        }
        if (periods.overlaps(sheetId, from, to)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another on this sheet");
        }
        Period saved;
        try {
            saved = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " from=" + saved.getFromDate() + " to=" + saved.getToDate()
                + (saved.getClaimCap() == null ? "" : " cap=" + saved.getClaimCap()));
        history.record(sheetId);
        return saved;
    }

    /** Generate one period per calendar month from the from-date's month to the to-date's month
     *  (the from-date the sheet's today when none is given), each running from the first to the last
     *  day of its month and named yyyy-mm; a month whose name is in use on the sheet, or whose days
     *  overlap a period on it, is left out. Refused when the to-date is before the from-date. */
    @Transactional
    public synchronized List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        sheets.load(sheetId, user);
        if (from == null) {
            from = sheets.today(sheetId);
        }
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date");
        }
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name) || periods.overlaps(sheetId, first, last)) {
                continue;
            }
            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
            made.add(saved);
        }
        history.record(sheetId);
        return made;
    }

    /** Generate the twelve monthly periods of the fiscal year named by the year, as {@link #generate}
     *  does, from the first day of the sheet's fiscal year start month in that year. */
    @Transactional
    public synchronized List<Period> generateFiscalYear(String sheetId, String user, int year) {
        LocalDate first = LocalDate.of(year, sheets.fiscalStartMonth(sheetId), 1);
        return generate(sheetId, user, first, first.plusMonths(12).minusDays(1));
    }

    /** The fiscal year a day falls in (FYyyyy), with fiscal years starting on the first day of the
     *  month: named by the calendar year that first day falls in. */
    public static String fiscalYear(LocalDate day, int fiscalStartMonth) {
        return "FY" + (day.getMonthValue() >= fiscalStartMonth ? day.getYear() : day.getYear() - 1);
    }

    /** Close a period (an open or a soft-closed one), fixing its due-total at what it is now; refused when the permission matrix does
     *  not allow the user's role to close, or it is already closed. */
    @Transactional
    public Period close(String sheetId, String user, long periodId) {
        }
    }

    /** The period form: a required name, the required days it runs from and to, and the most open
     *  or pending claims a person may have in it (a whole number of 1 or more; null for no cap). */
    public record PeriodForm(@NotBlank @Size(max = 100) String name, @NotNull LocalDate from,
            @NotNull LocalDate to, @Min(1) Integer cap) {
    }

    /** The generate form: the day whose month the periods start from (the sheet's today when none
     *  is given), and the required day whose month they end with. */
    public record GenerateForm(LocalDate from, @NotNull LocalDate to) {
    }

    /** The generate fiscal year form: the required year (yyyy) the fiscal year is named by. */
    public record GenerateFyForm(@NotBlank @Pattern(regexp = "\\s*\\d{4}\\s*") String year) {

        int yearValue() {
            return Integer.parseInt(year.trim());
        }
    }

    private final PeriodService service;
    private final SheetService sheets;
    private final History history;

    public PeriodController(PeriodService service, SheetService sheets, History history) {
        this.service = service;
        this.sheets = sheets;
        this.history = history;
    }

    /** The view of a period on the sheet. */
    private PeriodView view(String sheetId, Period period) {
        return PeriodView.of(period, sheets.fiscalStartMonth(sheetId));
    }

    /** The periods on the sheet, earliest first; as of a day when one is given, as they stood at the
     *  end of it (see {@link History}). */
    @GetMapping
    public List<PeriodView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
            LocalDate asOf) {
        List<Period> periods = asOf != null ? history.asOf(sheetId.trim(), asOf).periods()
                : service.list(sheetId.trim());
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return periods.stream().map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PeriodView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PeriodForm form) {
        return view(sheetId.trim(), service.add(sheetId.trim(), user.trim(), form.name().trim(), form.from(), form.to(), form.cap()));
    }

    @PostMapping("/generate")
    public List<PeriodView> generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateForm form) {
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return service.generate(sheetId.trim(), user.trim(), form.from(), form.to()).stream()
                .map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping("/generate-fy")
    public List<PeriodView> generateFy(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateFyForm form) {
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return service.generateFiscalYear(sheetId.trim(), user.trim(), form.yearValue()).stream()
                .map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping("/{periodId}/close")
    public PeriodView close(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.close(sheetId.trim(), user.trim(), periodId));
    }

  }

  /** Add a period; refused when it ends before it starts, its name is in use or it overlaps another. */
  add(form: PeriodForm): Promise<Period> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(this.http.post<Period>(this.url(sheetId), form, { headers: { 'X-User': user } }));
  }

  /** Generate one period per calendar month from the from-date's month to the to-date's month,
   *  leaving out a month whose name is in use or that overlaps a period; the from-date is the
   *  sheet's today when blank. Refused when the to-date is before the from-date. */
  generate(from: string, to: string): Promise<Period[]> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<Period[]>(`${this.url(sheetId)}/generate`, { from: from || null, to },
        { headers: { 'X-User': user } }),
    );
  }

  /** Generate the twelve monthly periods of the fiscal year named by the year (yyyy), as
   *  {@link generate} does. */
  generateFy(year: string): Promise<Period[]> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<Period[]>(`${this.url(sheetId)}/generate-fy`, { year }, { headers: { 'X-User': user } }),
    );
  }

  /** Paste opening balances, lines of name,period,amount, each adding the amount to the person's
   *  carried figure for the period; all lines are checked first and any error refuses the whole
   *  paste. Gives how many lines went through and the periods changed. */
  importOpenings(text: string): Promise<{ added: number; periods: Period[] }> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
import { HttpErrorResponse } from '@angular/common/http';
import { Component, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Period, Periods } from '../../core/periods';
import { FigurePipe } from '../../core/figure';

const DAY = /^\d{4}-\d{2}-\d{2}$/;

// The periods on the sheet with each one's due-total, and the form that adds a period.
@Component({
  selector: 'app-period-form',
  imports: [ReactiveFormsModule, FigurePipe],
  template: `
    <section aria-labelledby="periods-heading">
      <h2 id="periods-heading">Periods</h2>
